




"use strict";

const WebpackError = require("../errors/WebpackError");
const {
	evaluateToIdentifier
} = require("../javascript/JavascriptParserHelpers");
const ImportMetaContextDependency = require("./ImportMetaContextDependency");
























function createPropertyParseError(parser, prop, expect) {
	return createError(
		`Parsing import.meta.webpackContext options failed. Unknown value for property ${JSON.stringify(
			
			(prop.key).name
		)}, expected type ${expect}.`,
		parser.getLocation(prop.value)
	);
}







function createError(msg, loc) {
	const error = new WebpackError(msg);
	error.name = "ImportMetaContextError";
	error.loc = loc;
	return error;
}

const PLUGIN_NAME = "ImportMetaContextDependencyParserPlugin";

module.exports = class ImportMetaContextDependencyParserPlugin {
	




	apply(parser) {
		parser.hooks.evaluateIdentifier
			.for("import.meta.webpackContext")
			.tap(PLUGIN_NAME, (expr) =>
				evaluateToIdentifier(
					"import.meta.webpackContext",
					"import.meta",
					() => ["webpackContext"],
					true
				)(expr)
			);
		parser.hooks.call
			.for("import.meta.webpackContext")
			.tap(PLUGIN_NAME, (expr) => {
				if (expr.arguments.length < 1 || expr.arguments.length > 2) return;
				const [directoryNode, optionsNode] = expr.arguments;
				if (optionsNode && optionsNode.type !== "ObjectExpression") return;
				const requestExpr = parser.evaluateExpression(
					 (directoryNode)
				);
				if (!requestExpr.isString()) return;
				const request =  (requestExpr.string);
				
				const errors = [];
				let regExp = /^\.\/.*$/;
				let recursive = true;
				
				let mode = "sync";
				
				let include;
				
				let exclude;
				
				const groupOptions = {};
				
				let chunkName;
				
				let exports;
				if (optionsNode) {
					for (const prop of  (optionsNode)
						.properties) {
						if (prop.type !== "Property" || prop.key.type !== "Identifier") {
							errors.push(
								createError(
									"Parsing import.meta.webpackContext options failed.",
									parser.getLocation(optionsNode)
								)
							);
							break;
						}
						switch (prop.key.name) {
							case "regExp": {
								const regExpExpr = parser.evaluateExpression(
									 (prop.value)
								);
								if (!regExpExpr.isRegExp()) {
									errors.push(createPropertyParseError(parser, prop, "RegExp"));
								} else {
									regExp =  (regExpExpr.regExp);
								}
								break;
							}
							case "include": {
								const regExpExpr = parser.evaluateExpression(
									 (prop.value)
								);
								if (!regExpExpr.isRegExp()) {
									errors.push(createPropertyParseError(parser, prop, "RegExp"));
								} else {
									include = regExpExpr.regExp;
								}
								break;
							}
							case "exclude": {
								const regExpExpr = parser.evaluateExpression(
									 (prop.value)
								);
								if (!regExpExpr.isRegExp()) {
									errors.push(createPropertyParseError(parser, prop, "RegExp"));
								} else {
									exclude = regExpExpr.regExp;
								}
								break;
							}
							case "mode": {
								const modeExpr = parser.evaluateExpression(
									 (prop.value)
								);
								if (!modeExpr.isString()) {
									errors.push(createPropertyParseError(parser, prop, "string"));
								} else {
									mode =  (
										modeExpr.string
									);
								}
								break;
							}
							case "chunkName": {
								const expr = parser.evaluateExpression(
									 (prop.value)
								);
								if (!expr.isString()) {
									errors.push(createPropertyParseError(parser, prop, "string"));
								} else {
									chunkName = expr.string;
								}
								break;
							}
							case "exports": {
								const expr = parser.evaluateExpression(
									 (prop.value)
								);
								if (expr.isString()) {
									exports = [[ (expr.string)]];
								} else if (expr.isArray()) {
									const items =
										
										(expr.items);
									if (
										items.every((i) => {
											if (!i.isArray()) return false;
											const innerItems =
												 (i.items);
											return innerItems.every((i) => i.isString());
										})
									) {
										exports = [];

										for (const i1 of items) {
											
											const export_ = [];
											for (const i2 of  (
												i1.items
											)) {
												export_.push( (i2.string));
											}
											exports.push(export_);
										}
									} else {
										errors.push(
											createPropertyParseError(
												parser,
												prop,
												"string|string[][]"
											)
										);
									}
								} else {
									errors.push(
										createPropertyParseError(parser, prop, "string|string[][]")
									);
								}
								break;
							}
							case "prefetch": {
								const expr = parser.evaluateExpression(
									 (prop.value)
								);
								if (expr.isBoolean()) {
									groupOptions.prefetchOrder = 0;
								} else if (expr.isNumber()) {
									groupOptions.prefetchOrder = expr.number;
								} else {
									errors.push(
										createPropertyParseError(parser, prop, "boolean|number")
									);
								}
								break;
							}
							case "preload": {
								const expr = parser.evaluateExpression(
									 (prop.value)
								);
								if (expr.isBoolean()) {
									groupOptions.preloadOrder = 0;
								} else if (expr.isNumber()) {
									groupOptions.preloadOrder = expr.number;
								} else {
									errors.push(
										createPropertyParseError(parser, prop, "boolean|number")
									);
								}
								break;
							}
							case "fetchPriority": {
								const expr = parser.evaluateExpression(
									 (prop.value)
								);
								if (
									expr.isString() &&
									["high", "low", "auto"].includes(
										 (expr.string)
									)
								) {
									groupOptions.fetchPriority =
										 (
											expr.string
										);
								} else {
									errors.push(
										createPropertyParseError(
											parser,
											prop,
											'"high"|"low"|"auto"'
										)
									);
								}
								break;
							}
							case "recursive": {
								const recursiveExpr = parser.evaluateExpression(
									 (prop.value)
								);
								if (!recursiveExpr.isBoolean()) {
									errors.push(
										createPropertyParseError(parser, prop, "boolean")
									);
								} else {
									recursive =  (recursiveExpr.bool);
								}
								break;
							}
							default:
								errors.push(
									createError(
										`Parsing import.meta.webpackContext options failed. Unknown property ${JSON.stringify(
											prop.key.name
										)}.`,
										parser.getLocation(optionsNode)
									)
								);
						}
					}
				}
				if (errors.length) {
					for (const error of errors) parser.state.current.addError(error);
					return;
				}

				const dep = new ImportMetaContextDependency(
					{
						request,
						include,
						exclude,
						recursive,
						regExp,
						groupOptions,
						chunkName,
						referencedExports: exports,
						mode,
						category: "esm"
					},
					 (expr.range)
				);
				dep.loc = parser.getLocation(expr);
				dep.optional = Boolean(parser.scope.inTry);
				parser.state.current.addDependency(dep);
				return true;
			});
	}
};
